      exp:`Le Coran emploie l'impératif (فِعْلُ الأَمْرِ) massivement pour exprimer les obligations cultuelles et morales. Formation : pour le pluriel, enlever le préfixe تـ du مضارع + ـوا à la fin (تُقِيمُونَ → أَقِيمُوا). Pour le singulier : enlever تـ et ajouter une voyelle initiale si nécessaire (تَسْجُدُ → اسْجُدْ). Le وَاو de سُكُون à la fin des formes plurielles (وارْكَعُوا) est muet devant une voyelle.`,
