      excerptP:`ولا تشركوا به شيئا · ولا تقتلوا النفس`,
      exp:`La prohibition (النَّهْي) est formée de : لَا الناهية + المضارع المجزوم. La لَا ici est différente de لَا النافية (négation) : elle exige le jussif (مجزوم). Exemple : لَا تُشْرِكُوا — le وا final perd son ن. Dans le Coran, les 10 commandements de la sourate Al-Anʿām (6:151-153) présentent une série de نَهْي avec لَا الناهية.`,
