      excerptP:`أفلا تعقلون · هل جزاء الإحسان إلا الإحسان`,
      exp:`Le Coran emploie l'interrogation (الاستفهام) de trois manières : 1) الاستفهام الحقيقي (vraie question) · 2) الاستفهام الإنكاري (reproche/négation : أَفَلَا... ? = "voyons, vous ne...!") · 3) الاستفهام التقريري (affirmation par la question : هَلْ جَزَاء...? = "la récompense n'est-elle pas...?"). Le أ préfixé à فَلَا crée l'effet de surprise emphatique.`,
