      excerptP:`لئن شكرتم لأزيدنكم`,
      exp:`لَئِن est composée de لَام + إِن. Cette لَام est لَامُ التَّوْطِئَةِ (lam d'introduction au serment) et annonce un serment implicite. La réponse lَأَزِيدَنَّكُمْ commence par لَام + نُون التَّوْكِيد الثَّقِيلَة (ـنَّ), ce qui crée un double renforcement : serment + emphase. C'est une des structures les plus énergiques du Coran. La construction complète : لَئِنْ + شرط + لَـ + مضارع + نَّ.`,
