        {v:`التوكيد المتعدد`,f:`إِنَّا نَحْنُ... لَحَافِظُونَ`,m:`Leçon 18`,fr:`Emphase maximale`},
        {v:`إِنَّمَا الحصرية`,f:`إِنَّمَا الْمُؤْمِنُونَ إِخْوَةٌ`,m:`Leçon 10`,fr:`Restriction exclusive`},
        {v:`القسم + لام التوكيد`,f:`لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ`,m:`Leçon 17`,fr:`Serment emphatique`}
