        {w:`وَإِذَا تُلِيَتْ عَلَيْهِمْ آيَاتُهُ`,t:`et qui, quand Ses versets leur sont récités`},
        {w:`زَادَتْهُمْ إِيمَانًا`,t:`voient leur foi augmenter`},
        {w:`وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ`,t:`et qui s'en remettent à leur Seigneur`}
