        {w:`وَرَضُوا عَنْهُ`,t:`et ils L'agréent`},
        {w:`حَسْبُنَا اللهُ`,t:`Dieu nous suffit`},
        {w:`وَنِعْمَ الْوَكِيلُ`,t:`et quel excellent Garant !`}
